113	/// Emit an `MdQuotePrefix` node for a single `>` marker.
114	///
115	/// Consumes: [0-3 spaces as pre-marker indent] `>` [optional space as post-marker space]
116	/// Returns whether a post-marker space was consumed.
117	fn emit_quote_prefix_node(p: &mut MarkdownParser) -> bool {
118	    let prefix_m = p.start();
119	    let Some(marker_space) = emit_quote_prefix_tokens(p, false) else {
120	        prefix_m.abandon(p);
121	        return false;
122	    };
123	
124	    prefix_m.complete(p, MD_QUOTE_PREFIX);
125	    marker_space
126	}
