93	        // In Markdown, whitespace is significant and included in token text,
94	        // so we check if the token starts with a space or tab character.
95	        let text = p.cur_text();
96	        let token_starts_with_whitespace = text.starts_with(' ') || text.starts_with('\t');
97	        if !token_starts_with_whitespace {
