    let is_thematic_break_candidate = p.at(T![-])
        || p.at(T![*])
        || p.at(UNDERSCORE)
        || p.at(DOUBLE_UNDERSCORE)
        || (p.at(MD_TEXTUAL_LITERAL) && is_thematic_break_candidate_text(p.cur_text()));

